 {id:'bv',label:'Uso de la B y la V',short:'B y V',emoji:'🅱️',color:'#8ce6ba',tag:'Ortografía · reglas y excepciones',description:'Supera las trampas de la ortografía.'},
 {id:'diacritica',label:'Tilde diacrítica',short:'Tilde diacrítica',emoji:'🔡',color:'#b9e3ff',tag:'Monosílabos · significado y tilde',description:'Distingue palabras parecidas por lo que significan.'}
