const QUESTIONS_PER_TOPIC = 3;
const EXAM_QUESTION_COUNT = TOPICS.length * QUESTIONS_PER_TOPIC;
const LESSONS = {
 descripcion:{tip:'Haz un recorrido con la mirada: primero lo que está cerca, luego lo que hay detrás y finalmente lo más lejano. Cierra contando lo que te hace sentir.',intro:'Describir es explicar cómo es una persona, animal, objeto o paisaje para que quien lea pueda imaginarlo.',sections:[
  {title:'1. Qué es un texto descriptivo',body:`<p>En el <strong>texto descriptivo</strong> contamos cómo es algo. La descripción tiene que ser <strong>clara, exacta</strong> y basada en lo observado: no inventamos lo que no vemos.</p><p>Los <strong>adjetivos</strong> ayudan muchísimo: <em>arena húmeda, cielo luminoso, montañas altas, árbol rugoso</em>.</p><div class="example"><span class="example-label">Ejemplo</span>En la playa hay una <strong>orilla ancha</strong>. La arena es <strong>suave</strong> y el agua, <strong>tranquila</strong>.</div>`},
  {title:'2. La estructura de clase: cuatro partes',body:`<ol><li><strong>Título:</strong> breve y relacionado con el tema.</li><li><strong>Introducción (visión general):</strong> explica qué lugar describes y cómo es en conjunto.</li><li><strong>Desarrollo:</strong> detalla los elementos en orden: <strong>primer plano</strong> (cerca), <strong>segundo plano</strong> (zona central), <strong>fondo</strong> (lejos).</li><li><strong>Cierre:</strong> expresa las impresiones y sensaciones que transmite el paisaje.</li></ol><div class="example"><span class="example-label">Recorrido visual</span>👀 CERCA: arena y conchas → 🌳 MEDIO: árboles → ⛰️ LEJOS: montañas → 💛 CIERRE: «Me transmite tranquilidad».</div>`},
  {title:'3. Los sentidos y los conectores',body:`<p>No solo describimos <strong>lo que vemos</strong>: también podemos contar lo que <strong>oímos, olemos y sentimos</strong>.</p><p>Para unir las ideas, utiliza conectores espaciales: <strong>a la izquierda, a la derecha, junto a, al fondo, detrás de, cerca de, también</strong>.</p><div class="example"><span class="example-label">Ejemplo con sentidos</span>Al fondo se elevan las montañas azules. Se oye el murmullo del agua y se nota el aire fresco en la cara.</div>`},
  {title:'4. Autoevaluación: los 9 controles del cole',body:`<p>En la ficha de clase se revisan estos puntos:</p><ol><li>Título claro y relacionado.</li><li>Introducción con visión general.</li><li>Descripción clara y precisa, sin inventar.</li><li>Adjetivos apropiados.</li><li>Orden: primer plano, segundo plano y fondo.</li><li>Cierre con sensaciones o impresiones.</li><li>Frases bien construidas.</li><li>Conectores para unir ideas.</li><li>Ortografía y puntuación revisadas.</li></ol><div class="lesson-note">En el <strong>Taller de descripción</strong> puedes escribir tu propio texto y utilizar esta misma rúbrica.</div>`}
 ]},
 oracion:{tip:'Para hallar el sujeto, encuentra el verbo y pregunta «¿quién realiza la acción?». Comprueba que concuerda con el verbo. Puede estar escondido: sujeto elíptico.',intro:'Una oración puede dividirse en sujeto y predicado. Cada uno tiene una palabra principal: su núcleo.',sections:[
  {title:'1. Sujeto y predicado',body:`<p><strong>Sujeto:</strong> la parte de la oración que nos dice de quién o de qué estamos hablando.</p><p><strong>Predicado:</strong> lo que explicamos sobre ese sujeto.</p><div class="example"><span class="example-label">Analizamos la oración</span><span class="mark-sub">Los libros de aventuras</span> <span class="mark-pred">están en la estantería.</span><p class="microcopy">Violeta = sujeto. Verde = predicado.</p></div><p>El <strong>sujeto elíptico</strong> no está escrito, pero lo entendemos gracias al verbo: «<strong>Saltamos</strong> muy alto» → sujeto elíptico: <strong>nosotros/nosotras</strong>.</p>`},
  {title:'2. Los núcleos',body:`<p>El <strong>núcleo del sujeto</strong> suele ser un <strong>nombre</strong>. El <strong>núcleo del predicado</strong> es un <strong>verbo</strong>.</p><div class="example"><span class="example-label">Fíjate en las palabras subrayadas</span>Las <span class="mark-sub mark-core">niñas</span> del colegio <span class="mark-pred"><span class="mark-core">preparan</span> una obra de teatro.</span><p class="microcopy">Núcleo del sujeto: niñas. Núcleo del predicado: preparan.</p></div><p>Truco: primero identifica la acción (<em>preparan</em>), luego pregunta quién la hace (<em>las niñas del colegio</em>).</p>`},
  {title:'3. Qué es un sintagma nominal (SN)',body:`<p>El <strong>sintagma nominal</strong> es un conjunto de palabras formado alrededor de un <strong>nombre (núcleo)</strong>. Puede incluir <strong>determinantes</strong> y <strong>complementos del nombre (CN)</strong>.</p><div class="example"><span class="example-label">Desmontamos un SN</span><span class="mini-label">Los</span> <span class="mini-label">libros</span> <span class="mini-label">de aventuras</span><p><strong>Los</strong> = determinante · <strong>libros</strong> = núcleo · <strong>de aventuras</strong> = complemento del nombre.</p></div><p>Puede haber sintagmas nominales tanto en el <strong>sujeto</strong> como dentro del <strong>predicado</strong>.</p>`},
  {title:'4. Complementos del nombre',body:`<p>En la ficha aparecen <strong>tres formas</strong>:</p><table class="theory-table"><thead><tr><th>Tipo de CN</th><th>Ejemplo</th></tr></thead><tbody><tr><td>Adjetivo</td><td>Una falda <strong>larga</strong>.</td></tr><tr><td>Preposición + SN</td><td>Un paisaje <strong>de montaña</strong>.</td></tr><tr><td>«Que» + oración</td><td>El libro <strong>que me prestaste</strong>.</td></tr></tbody></table><p>Todos dan más información sobre el nombre al que acompañan.</p>`},
  {title:'5. Oraciones simples y compuestas',body:`<p>En los ejercicios se distingue entre <strong>oraciones simples</strong> (un solo verbo conjugado) y <strong>compuestas</strong> (más de un verbo conjugado).</p><div class="example"><span class="example-label">Ejemplos</span>Simple: <strong>Abre</strong> la puerta.<br>Compuesta: Mi amiga <strong>dice</strong> que <strong>vendrá</strong> mañana.</div><p>Para este tipo de ejercicios, cuenta las formas verbales conjugadas, no los nombres.</p>`}
 ]},
 tipos:{tip:'No mires solo el signo final. Pregúntate qué quiere hacer quien habla: informar, preguntar, emocionarse, pedir, dudar o desear.',intro:'Las oraciones se clasifican según la intención que tiene la persona que habla.',sections:[
  {title:'1. Los seis tipos',body:`<table class="theory-table"><thead><tr><th>Tipo</th><th>¿Para qué sirve?</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Enunciativa</strong></td><td>Informa de un hecho: afirmación o negación.</td><td>No hemos terminado la tarea.</td></tr><tr><td><strong>Interrogativa</strong></td><td>Formula una pregunta, directa o indirecta.</td><td>¿Dónde vive Marta?</td></tr><tr><td><strong>Exclamativa</strong></td><td>Expresa emoción o sentimiento.</td><td>¡Qué bonito es este paisaje!</td></tr><tr><td><strong>Imperativa</strong></td><td>Da órdenes, instrucciones, consejos o pide algo.</td><td>Por favor, cierra la puerta.</td></tr><tr><td><strong>Dubitativa</strong></td><td>Expresa duda o incertidumbre.</td><td>Quizá llegue tarde.</td></tr><tr><td><strong>Desiderativa</strong></td><td>Expresa deseos.</td><td>Ojalá mañana no llueva.</td></tr></tbody></table>`},
  {title:'2. Ojo con las trampas',body:`<p><strong>Enunciativa afirmativa:</strong> «Mi hermano ha perdido la mochila». <strong>Enunciativa negativa:</strong> «No conozco ese libro».</p><p>Una pregunta puede ser <strong>directa</strong> («¿Qué hora es?») o <strong>indirecta</strong> («No sé qué hora es»). La indirecta puede no llevar signos de interrogación.</p><div class="example"><span class="example-label">Duda ≠ deseo</span>«<strong>Quizás</strong> vayamos» → duda (dubitativa).<br>«<strong>Ojalá</strong> vayamos» → deseo (desiderativa).</div>`},
  {title:'3. Cambiar el tipo de una oración',body:`<p>En las fichas se transforma una oración para que exprese otra intención. Mantén la idea central y cambia la forma:</p><div class="example"><span class="example-label">Partimos de una información</span>Enunciativa: «Es una fotografía sensacional».<br>Exclamativa: «¡Es una fotografía sensacional!».</div><p>Recuerda incluir los <strong>signos de apertura y cierre</strong> en preguntas y exclamaciones.</p>`}
 ]},
 puntuacion:{tip:'Haz una pausa y piensa qué hace la frase: termina, enumera, explica, duda, cita o habla un personaje. Así sabrás qué signo necesita.',intro:'Los ocho signos de la ficha de clase ayudan a ordenar las ideas y a entender mejor un texto.',sections:[
  {title:'1. Los ocho signos',body:`<table class="theory-table"><thead><tr><th>Signo</th><th>Uso en los apuntes</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Punto .</strong></td><td>Termina una oración.</td><td>Hoy hace sol.</td></tr><tr><td><strong>Coma ,</strong></td><td>Separa elementos e introduce aclaraciones.</td><td>Compré pan, leche, fruta y queso.</td></tr><tr><td><strong>Punto y coma ;</strong></td><td>Separa oraciones relacionadas o partes de una enumeración compleja.</td><td>Fuimos a Madrid, España; Lisboa, Portugal; y París, Francia.</td></tr><tr><td><strong>Dos puntos :</strong></td><td>Introducen explicaciones, citas y enumeraciones.</td><td>Necesito tres cosas: lápiz, goma y regla.</td></tr><tr><td><strong>Puntos suspensivos …</strong></td><td>Indican pausa, duda o idea sin acabar.</td><td>No sé… quizá tengas razón.</td></tr><tr><td><strong>Comillas « »</strong></td><td>Encierran citas o palabras destacadas.</td><td>La profesora dijo: «Muy bien».</td></tr><tr><td><strong>Paréntesis ( )</strong></td><td>Añaden datos y aclaraciones.</td><td>Cervantes (1547-1616) escribió Don Quijote.</td></tr><tr><td><strong>Raya —</strong></td><td>Introduce el diálogo o intercala aclaraciones.</td><td>—¿Vienes conmigo? —preguntó Ana.</td></tr></tbody></table>`},
  {title:'2. Pausas y enumeraciones',body:`<p>En una lista sencilla, separamos los elementos con <strong>comas</strong> y podemos unir los dos últimos con «y»: <em>manzanas, peras y uvas</em>.</p><p>El <strong>punto y coma</strong> sirve cuando los elementos de la lista ya contienen comas, o para enlazar ideas relacionadas.</p><div class="example"><span class="example-label">Fíjate en la diferencia</span>Hoy llevo cuaderno, lápiz y goma.<br>Viajan Ana, de sexto A; Pablo, de sexto B; y Sara, de sexto C.</div>`},
  {title:'3. Diálogos, citas y aclaraciones',body:`<p>La <strong>raya (—)</strong> abre las intervenciones de los personajes. Las <strong>comillas</strong> reproducen palabras textuales. Los <strong>paréntesis</strong> añaden información que complementa la frase.</p><div class="example"><span class="example-label">Tres usos</span>—Vamos al parque —dijo Eva.<br>Eva dijo: «Vamos al parque».<br>Eva (mi vecina) vive cerca.</div>`},
  {title:'4. Cómo revisar un texto',body:`<ol><li>Busca dónde termina cada oración y coloca el <strong>punto</strong>.</li><li>Encuentra las <strong>listas</strong> y sus comas.</li><li>Si anuncias una lista o una cita, usa <strong>dos puntos</strong>.</li><li>Si alguien habla, revisa <strong>raya</strong> y <strong>comillas</strong>.</li><li>Para una aclaración adicional, considera los <strong>paréntesis</strong>.</li><li>Si hay duda o pausa intencionada, usa <strong>puntos suspensivos</strong>.</li></ol><div class="lesson-note">Los ejercicios de clase piden añadir comas, puntos, puntos suspensivos, raya, dos puntos y paréntesis; también corregir un texto entero.</div>`}
 ]},
 bv:{tip:'En vez de adivinar, busca la pista: ¿empieza por bu-/bur-/bus-?, ¿termina en -bir o -bilidad?, ¿es un verbo en -aba?, ¿es un adjetivo en -ivo/-iva?',intro:'Estas son las reglas y excepciones que aparecen en la ficha de ortografía B/V.',sections:[
  {title:'1. Cuándo se escribe B',body:`<ul><li>Palabras que empiezan por <strong>bu-, bur-, bus-</strong>: <em>bufanda, burbuja, buscar</em>.</li><li>Verbos terminados en <strong>-bir</strong>: <em>escribir, recibir</em>. <strong>Excepciones:</strong> <em>hervir, servir, vivir</em>.</li><li>Palabras terminadas en <strong>-bilidad</strong>: <em>amabilidad, responsabilidad</em>. <strong>Excepción de la ficha:</strong> <em>movilidad</em>.</li><li>Pretérito imperfecto de indicativo de verbos de la primera conjugación (-ar): <strong>-aba, -abas, -ábamos…</strong>: <em>cantaba, caminábamos, jugaban</em>.</li></ul><div class="example"><span class="example-label">Truco -ABA</span>«Ayer, cuando era pequeña, <strong>jugaba</strong> en el parque». La terminación <strong>-aba</strong> se escribe con B.</div>`},
  {title:'2. Cuándo se escribe V',body:`<ul><li>Adjetivos llanos terminados en <strong>-ava, -ave, -avo, -eva, -eve, -evo, -ivo, -iva</strong>: <em>suave, nueva, octavo, breve, activo, creativa</em>.</li><li>Formas verbales con sonido /b/ cuyo infinitivo <strong>no contiene b ni v</strong>, con la excepción de las terminaciones <strong>-aba, -abas, -ábamos…</strong> de los verbos en -ar: <em>tuve</em> (tener), <em>anduve</em> (andar), <em>estuve</em> (estar).</li></ul><div class="example"><span class="example-label">Compara</span><strong>cantaba</strong> → B por ser imperfecto de <em>cantar</em>.<br><strong>anduve</strong> → V porque el infinitivo <em>andar</em> no tiene ni B ni V, y no acaba en -aba.</div>`},
  {title:'3. Excepciones que pueden salir',body:`<p><strong>Vivir, servir y hervir</strong> terminan en -vir, no siguen la regla general de los verbos en -bir.</p><p><strong>Movilidad</strong> lleva V, aunque la mayoría de las palabras en -bilidad llevan B.</p><p>Si una palabra te hace dudar, busca la <strong>regla completa</strong> y luego comprueba si tiene alguna excepción.</p>`},
  {title:'4. Cómo practicar según las fichas',body:`<p>En clase se ha trabajado de varias maneras: <strong>completar b/v</strong> dentro de un texto, <strong>conjugar</strong> verbos en pretérito imperfecto y <strong>formar adjetivos</strong> terminados en -ivo/-iva.</p><div class="example"><span class="example-label">Tres mini retos</span>completar: <strong>_ufanda → bufanda</strong><br>conjugar: <strong>cantar → cantaban</strong><br>formar adjetivo: <strong>crear → creativo/creativa</strong></div>`}
 ]},
 diacritica:{tip:'Lee la frase completa y pregunta qué significa la palabra. ¿Es un pronombre, una cantidad o el verbo dar? El significado te ayuda a decidir si lleva tilde.',intro:'La tilde diacrítica distingue algunas palabras que se escriben casi igual, pero cumplen funciones distintas.',sections:[
  {title:'1. Pares que cambian de significado',body:`<table class="theory-table"><thead><tr><th>Sin tilde</th><th>Con tilde</th></tr></thead><tbody><tr><td><strong>de</strong>: preposición · El vaso es de cristal.</td><td><strong>dé</strong>: forma del verbo dar · Espero que me dé la nota.</td></tr><tr><td><strong>el</strong>: artículo · El cuaderno es azul.</td><td><strong>él</strong>: pronombre · Lo guardé para él.</td></tr><tr><td><strong>mas</strong>: equivale a pero · Quise ir, mas no pude.</td><td><strong>más</strong>: cantidad o comparación · Quiero más agua.</td></tr><tr><td><strong>mi</strong>: posesivo · Mi casa está cerca.</td><td><strong>mí</strong>: pronombre · Lo hicieron por mí.</td></tr><tr><td><strong>se</strong>: pronombre · Se peina.</td><td><strong>sé</strong>: saber o ser · No lo sé. Sé amable.</td></tr><tr><td><strong>si</strong>: condición o nota musical · Si llueve, llevo paraguas.</td><td><strong>sí</strong>: afirmación o pronombre · Sí, lo hizo por sí misma.</td></tr><tr><td><strong>te</strong>: pronombre · Te llamo luego.</td><td><strong>té</strong>: bebida · Tomamos té. En plural: tés.</td></tr><tr><td><strong>tu</strong>: posesivo · Tu mochila pesa.</td><td><strong>tú</strong>: pronombre · Tú puedes.</td></tr></tbody></table><p class="lesson-note">Las notas musicales <em>mi</em> y <em>si</em> se escriben sin tilde.</p>`},
  {title:'2. Aun y aún',body:`<p><strong>Aún</strong> lleva tilde cuando significa <strong>todavía</strong>: «Aún no ha llegado».</p><p><strong>Aun</strong> no lleva tilde cuando significa <strong>incluso</strong>, <strong>hasta</strong> o <strong>aunque</strong>; también aparece en «ni aun así» con sentido de «ni siquiera»: «Aun con lluvia, salimos»; «Ni aun así se rindió».</p><div class="example"><span class="example-label">Truco</span>Prueba a sustituirla: si puedes decir «todavía», escribe <strong>aún</strong>. Si encaja «incluso» o «aunque», escribe <strong>aun</strong>.</div><p class="lesson-note">En <em>aún</em>, la tilde marca el hiato; la norma actual no la considera propiamente una tilde diacrítica.</p>`},
  {title:'3. Cómo decidir si lleva tilde',body:`<ol><li>Lee la oración entera y busca el significado.</li><li>Comprueba la función: artículo o pronombre, posesivo o pronombre, preposición o forma verbal.</li><li>En <strong>aun/aún</strong>, prueba los trucos «todavía» e «incluso/aunque».</li><li>No pongas tilde a todos los monosílabos: <strong>fue, dio, fe</strong> y <strong>ti</strong> se escriben sin ella.</li></ol><div class="example"><span class="example-label">Mira el contraste</span><strong>Tú</strong> sabes que <strong>tu</strong> equipo ganó. / <strong>Él</strong> dijo que <strong>el</strong> té es para <strong>mí</strong>.</div>`}
 ]}
};

// Banco de retos: algunos adaptan el formato y ejemplos de las fichas;
// otros son originales, construidos sobre las mismas definiciones y reglas.
const QUESTIONS=[];
function mc(topic,prompt,options,answer,why,how,hint='',extra={}){QUESTIONS.push({id:`q${String(QUESTIONS.length+1).padStart(3,'0')}`,topic,type:'choice',prompt,options,answer,why,how,hint,...extra});}
function fill(topic,prompt,answer,why,how,hint='',alternates=[],extra={}){QUESTIONS.push({id:`q${String(QUESTIONS.length+1).padStart(3,'0')}`,topic,type:'fill',prompt,answer,alternates,why,how,hint,...extra});}

// TEXTO DESCRIPTIVO: estructura, orden espacial, adjetivos, sentidos, rúbrica.
mc('descripcion','¿Para qué sirve principalmente un texto descriptivo?',['Para contar una aventura por orden temporal.','Para explicar cómo es algo y ayudar a imaginarlo.','Para dar instrucciones de un juego.'],1,'El texto descriptivo presenta características de una persona, objeto, animal o paisaje.','Pregunta qué se intenta comunicar: cómo es → descripción; qué ocurrió → narración; qué hacer → instrucciones.','Piensa en la palabra «describir».');
mc('descripcion','¿Qué debe aparecer al principio de una descripción de paisaje?',['Una visión general del lugar.','Solo la opinión final del autor.','Una lista de personajes que hablan.'],0,'En los apuntes, la introducción ofrece una primera impresión global del paisaje.','Después del título, presenta el lugar antes de pasar a sus detalles.','Repasa la segunda parte de la estructura.');
mc('descripcion','¿Cuál es el orden recomendado para describir un paisaje?',['Fondo → cierre → título → primer plano.','Primer plano → segundo plano → fondo.','Fondo → primer plano → introducción.'],1,'La ficha propone un recorrido espacial ordenado: lo cercano, lo central y lo lejano.','Sitúa mentalmente tus ojos: cerca → medio → lejos.','Empieza por lo que puedes tocar más fácilmente.');
mc('descripcion','¿Cuál de estos títulos es el mejor para describir una playa?',['Una tarde de juegos con Marta','¡Auxilio, una ola gigante!','La playa tranquila al amanecer'],2,'El título debe ser breve y relacionado con el paisaje que vamos a describir.','Antes de elegir, comprueba si anuncia el lugar y no una acción o un suceso.','Elige el título que te deja imaginar el lugar.');
mc('descripcion','¿Qué parte incluye «El paisaje me transmite mucha paz»?',['Cierre: impresiones y sensaciones.','Descripción del primer plano.','Título.'],0,'La frase no presenta un elemento del paisaje: comunica lo que siente quien lo observa.','Cuando dices «me transmite», «me hace sentir» o «me parece», suele ser el cierre.','Identifica la emoción.');
mc('descripcion','¿Qué palabra es un adjetivo en «La arena húmeda cubría la orilla»?',['arena','húmeda','orilla'],1,'«Húmeda» indica cómo está la arena; aporta una cualidad del nombre.','Pregunta «¿cómo es la arena?» → húmeda.','Un adjetivo describe una cualidad.');
mc('descripcion','¿Cuál de estas frases describe con mayor precisión?',['Había cosas bonitas.','Se estaba muy bien.','La arena dorada estaba húmeda junto a las rocas.'],2,'La última frase nombra elementos concretos y añade adjetivos observables.','Una descripción clara combina un nombre preciso con alguna característica real: arena + dorada + húmeda.','Busca detalles que se puedan imaginar.');
mc('descripcion','En «Se escucha el suave sonido de las olas», ¿qué sentido usamos?',['Oído','Vista','Olfato'],0,'«Escucha» y «sonido» indican que la descripción incorpora información auditiva.','Busca la palabra que alude a un sentido; aquí es «escucha».','¿Con qué órgano percibimos los sonidos?');
mc('descripcion','¿Cuál de estos conectores sirve para indicar que algo está lejos?',['Por último','Al fondo','Ayer'],1,'«Al fondo» es un conector espacial que sitúa elementos alejados.','Para ordenar un paisaje usa expresiones como «en primer plano», «detrás» y «al fondo».','Piensa en la posición del objeto.');
mc('descripcion','¿Qué frase es un buen ejemplo de visión general?',['Este es un paisaje de montaña rodeado de bosques.','Sobre una piedra hay tres pequeñas hormigas.','El aire frío me hizo sentir felicidad.'],0,'La visión general presenta el lugar antes de los detalles concretos o las emociones finales.','Primero di qué paisaje es; luego describe las piedras, árboles y demás detalles.','¿Cuál presenta el conjunto?');
mc('descripcion','¿Qué dato debería ir en el primer plano?',['Las montañas lejanas.','Las conchas a nuestros pies.','Las nubes del horizonte.'],1,'El primer plano contiene lo más próximo al observador, como las conchas que están a sus pies.','Imagínate allí: lo más cercano va primero.','Primer plano significa «cerca».');
mc('descripcion','¿Qué es importante evitar en una descripción de observación?',['Usar adjetivos.','Utilizar conectores.','Inventar elementos que no están en el paisaje.'],2,'La ficha pide que sea clara, exacta y basada en lo que observamos, sin inventar.','Antes de escribir cada detalle, pregúntate si lo has observado o percibido.','Una descripción exacta cuenta lo que existe.');
mc('descripcion','¿Cuál es el mejor conector para unir una idea sobre otra zona?',['A la derecha','Por eso mismo sucedió','Hace tres años'],0,'«A la derecha» indica una nueva posición en el espacio, justo como en la descripción de clase.','Los conectores espaciales sitúan: izquierda, derecha, junto a, detrás, al fondo.','¿Cuál expresa lugar?');
mc('descripcion','¿Qué actividad formaba parte de la rúbrica de autoevaluación de clase?',['Contar el número de personajes que hablan.','Revisar ortografía y puntuación.','Escribir siempre en verso.'],1,'En la rúbrica de los apuntes se revisan tanto el contenido como la ortografía y puntuación.','Después de redactar, lee oración por oración y busca signos y errores.','Recuerda la última revisión antes de entregar.');
mc('descripcion','¿Cuál de estos cierres incluye una sensación?',['La montaña tiene dos picos.','Hay tres árboles en la ladera.','El silencio de este paisaje me hace sentir tranquila.'],2,'Un cierre descriptivo puede expresar el efecto emocional o sensorial del lugar.','Comprueba si la frase dice cómo te sientes, no solo qué objetos hay.','Busca «me hace sentir».');
mc('descripcion','Si ya has hablado de la orilla y de las palmeras centrales, ¿qué describirías después?',['Las montañas del horizonte.','El título de nuevo.','La misma orilla por segunda vez.'],0,'Después del primer y segundo plano, la ficha propone describir el fondo.','Respeta la secuencia espacial para que el lector recorra el paisaje sin perderse.','¿Qué zona falta: cerca, media o lejana?');
fill('descripcion','Completa el conector espacial: «_____ se ven las montañas nevadas».','Al fondo','«Al fondo» señala lo que está lejos y ayuda a ordenar la descripción.','Al escribir sobre montañas alejadas, utiliza un conector que marque distancia.','Son dos palabras.');
mc('descripcion','¿Qué frase combina dos sentidos de forma apropiada?',['El viento soplaba azul y el lago corría rápido.','Veía un cielo naranja y oía pájaros entre las ramas.','La mochila hizo una pregunta.'],1,'En una descripción puedes combinar lo que ves (cielo naranja) y lo que oyes (pájaros).','Localiza primero el dato visual y después el auditivo.','¿Cuál tiene vista y oído?');

// ORACIÓN: sujeto, predicado, núcleos, elíptico, SN, CN, simples y compuestas.
mc('oracion','En «Los alumnos preparan una exposición», ¿cuál es el sujeto?',['Preparan una exposición','Los alumnos','Una exposición'],1,'«Los alumnos» es aquello de lo que hablamos y concuerda con el verbo «preparan».','Localiza el verbo «preparan». Pregunta «¿quiénes preparan?» → los alumnos.','Pregunta quién realiza la acción.');
mc('oracion','En «La bicicleta roja necesita una reparación», ¿cuál es el predicado?',['La bicicleta roja','La bicicleta','Necesita una reparación'],2,'El predicado expresa lo que se dice del sujeto e incluye el verbo «necesita».','Separa primero el sujeto «La bicicleta roja»; el resto es el predicado.','¿Qué se dice de la bicicleta?');
mc('oracion','En «Los niños del colegio observaron aves», ¿cuál es el núcleo del sujeto?',['Niños','Colegio','Observaron'],0,'El núcleo del sujeto es el nombre principal: «niños». «Del colegio» añade información.','Identifica el sujeto completo y busca el nombre que dirige el grupo.','No confundas el nombre principal con su complemento.');
mc('oracion','En «Los jugadores celebraron la victoria», ¿cuál es el núcleo del predicado?',['Jugadores','Celebraron','Victoria'],1,'El núcleo del predicado es el verbo «celebraron».','Busca qué acción realizan los jugadores: «celebraron».','El núcleo del predicado siempre es un verbo.');
mc('oracion','En «Llegamos cansados a casa», ¿qué sujeto aparece?',['Los coches','Nosotros/nosotras, elíptico','La casa'],1,'El verbo «llegamos» indica primera persona del plural, aunque el sujeto no esté escrito.','Pregunta quién llega. La forma verbal termina en -amos: «nosotros/nosotras».','La pista está en la persona verbal.');
mc('oracion','En «Escuchaste atentamente las instrucciones», ¿cuál es el sujeto elíptico?',['Yo','Ellos/ellas','Tú'],2,'«Escuchaste» está en segunda persona del singular: el sujeto entendido es «tú».','Reescribe la oración incluyendo el sujeto: «Tú escuchaste…».','Piensa quién «escuchaste».');
mc('oracion','En «La casa de campo necesita reformas», ¿cuál es el sujeto completo?',['La casa de campo','Necesita reformas','De campo necesita'],0,'El sujeto es todo el grupo «La casa de campo», no solo su núcleo «casa».','El núcleo «casa» va con su determinante y complemento «de campo»: todo forma el sujeto.','No te quedes solo con el nombre principal.');
mc('oracion','En «Las flores del jardín crecen rápido», ¿cuál es el núcleo del sujeto?',['Jardín','Flores','Crecen'],1,'«Flores» es el nombre principal del sujeto «Las flores del jardín».','Pregunta de qué hablamos: de las flores. «Del jardín» solo las precisa.','El complemento del nombre no es el núcleo.');
mc('oracion','¿Qué es un sintagma nominal?',['Un grupo de palabras alrededor de un nombre.','Una palabra que siempre es verbo.','Una exclamación terminada en !'],0,'Un sintagma nominal se organiza alrededor de un nombre y puede tener determinantes y complementos.','Busca el nombre principal; luego observa qué palabras lo acompañan.','La N de SN significa nominal.');
mc('oracion','En «La falda larga», ¿qué tipo de complemento del nombre es «larga»?',['Que + oración','Adjetivo','Preposición + sintagma nominal'],1,'«Larga» es un adjetivo que describe una cualidad de la falda.','Comprueba si la palabra responde a «¿cómo es la falda?».','Es una palabra que expresa cualidad.');
mc('oracion','En «Un paisaje de montaña», ¿qué tipo de complemento es «de montaña»?',['Preposición + sintagma nominal','Adjetivo','Que + oración'],0,'«De montaña» comienza por la preposición «de» seguida de un nombre.','Mira cómo empieza el complemento: «de» + «montaña».','Fíjate en «de».');
mc('oracion','En «El libro que me prestaste», ¿cómo está construido el complemento?',['Solo un adjetivo','Preposición + sintagma nominal','Que + oración'],2,'«Que me prestaste» empieza por «que» y contiene el verbo «prestaste».','La pista es «que» seguido de una oración con verbo.','Busca «que» y un verbo.');
mc('oracion','En el sintagma «Las zapatillas blancas», ¿qué palabra es el determinante?',['Las','Zapatillas','Blancas'],0,'«Las» acompaña y presenta al nombre «zapatillas»; «blancas» es un adjetivo.','Divide el SN: determinante «las», núcleo «zapatillas», complemento «blancas».','Suele aparecer delante del nombre.');
mc('oracion','En «Los libros de aventuras», ¿qué grupo es el complemento del nombre?',['Los','Libros','De aventuras'],2,'«De aventuras» completa y especifica qué tipo de libros son.','El núcleo es «libros»; el grupo que lo precisa es «de aventuras».','No confundas núcleo y complemento.');
mc('oracion','«Abre la puerta inmediatamente». ¿Es simple o compuesta?',['Compuesta','Simple','No es una oración'],1,'La oración tiene un solo verbo conjugado: «abre».','Cuenta los verbos conjugados: uno → simple.','Cuenta verbos, no palabras.');
mc('oracion','«Elvira quiere que tú vayas a la fiesta». ¿Simple o compuesta?',['Compuesta','Simple','No se puede saber'],0,'Aparecen dos verbos conjugados: «quiere» y «vayas».','Subraya cada verbo conjugado. Dos → compuesta en este ejercicio.','Encuentra las dos acciones verbales.');
mc('oracion','«Ojalá me compren un helado». ¿Simple o compuesta?',['Compuesta','Simple','Dos sujetos'],1,'Solo aparece un verbo conjugado: «compren». La intención de deseo no cambia eso.','No confundas el tipo por intención con simple/compuesta: cuenta verbos.','¿Cuántos verbos conjugados ves?');
mc('oracion','«Mi hermana lee y yo dibujo». ¿Simple o compuesta?',['Simple','Compuesta','Sintagma nominal'],1,'Tiene dos verbos conjugados, «lee» y «dibujo», que se unen mediante «y».','Separa las dos acciones. Cada verbo conjugado suma uno.','Subraya «lee» y «dibujo».');
mc('oracion','En «Prepararon una sorpresa para su abuela», ¿qué sujeto elíptico entendemos?',['Ella','Ellos/ellas','Yo'],1,'«Prepararon» está en tercera persona del plural. El sujeto se sobreentiende: ellos o ellas.','Comprueba la forma verbal: prepararon → ellos/ellas prepararon.','La terminación es -aron.');
mc('oracion','En «Mi perro pequeño corre», ¿qué incluye el sujeto?',['Mi perro pequeño','Corre','Pequeño corre'],0,'El sujeto contiene el determinante «mi», el núcleo «perro» y el adjetivo «pequeño».','Busca quién corre y toma el grupo nominal completo, no solo el núcleo.','El adjetivo acompaña al sujeto.');
fill('oracion','Completa: «El núcleo del predicado es un _____».','verbo','En las fichas, la palabra más importante del predicado es el verbo.','Busca la acción: saltó, preparan, observaron… Todas son formas verbales.','Es una categoría de palabras.');
fill('oracion','Completa: «El sujeto que no está escrito, pero se entiende, se llama sujeto _____».','elíptico','Un sujeto elíptico se deduce por el verbo, como «nosotros» en «llegamos».','Busca la persona de la forma verbal y añade mentalmente el pronombre.','Empieza por e.', ['eliptico']);

// TIPOS DE ORACIONES: seis tipos, subtipos y transformaciones.
const typesWhy={enunciativa:'informa de un hecho',interrogativa:'plantea una pregunta',exclamativa:'expresa emoción o sentimiento',imperativa:'da una orden, consejo o petición',dubitativa:'manifiesta duda o posibilidad',desiderativa:'expresa un deseo'};
function typeQuestion(prompt,correct,clue,hint=''){let options=['Enunciativa','Interrogativa','Exclamativa','Imperativa','Dubitativa','Desiderativa'];let correctIdx=options.findIndex(x=>x.toLowerCase()===correct);mc('tipos',`¿Qué tipo de oración es «${prompt}»?`,options,correctIdx,`Es ${correct}: ${typesWhy[correct]}. ${clue}`,`No te fijes solo en la puntuación: piensa en la intención del hablante. Aquí ${typesWhy[correct]}.`,hint||'Pregunta qué quiere hacer la persona que habla.',{family:'types'});}
typeQuestion('¿Vendrás mañana a jugar?','interrogativa','Los signos ¿? muestran una pregunta directa.');
typeQuestion('¡Qué frío hace hoy!','exclamativa','La expresión «qué frío» transmite sorpresa o emoción.');
typeQuestion('Quizás podamos ir al parque después.','dubitativa','La palabra «quizás» expresa incertidumbre.');
typeQuestion('Abre la ventana, por favor.','imperativa','Se pide que alguien abra la ventana.');
typeQuestion('Mi hermano ha perdido su mochila.','enunciativa','Solo se comunica un hecho.');
typeQuestion('Bebed el agua despacio.','imperativa','Se da una instrucción o consejo.');
typeQuestion('No conozco ese libro.','enunciativa','Es una información negativa.');
typeQuestion('Que tengas suerte.','desiderativa','La persona expresa un deseo.');
typeQuestion('¡Cuántos libros hay!','exclamativa','Expresa sorpresa ante la cantidad de libros.');
typeQuestion('Tal vez llueva el domingo.','dubitativa','«Tal vez» expresa posibilidad, no seguridad.');
typeQuestion('Ojalá mañana haga sol.','desiderativa','«Ojalá» expresa un deseo.');
typeQuestion('¿Qué lees?','interrogativa','Se busca información mediante una pregunta.');
typeQuestion('Pedro no contestó.','enunciativa','Informa de una acción que no ocurrió.');
typeQuestion('Dime la verdad.','imperativa','Solicita a otra persona que diga algo.');
typeQuestion('No sé qué hora es.','interrogativa','Contiene una pregunta indirecta («qué hora es»), aunque la oración completa no lleva ¿?.','Piensa en una pregunta que se ha incorporado dentro de la oración.');
mc('tipos','¿Cuál es una oración enunciativa negativa?',['No hemos terminado la tarea.','¡Qué alegría!','¿Has terminado?'],0,'La primera informa de un hecho negándolo con «no».','Enunciativa = informa. Negativa = incluye una negación.','Busca «no» y ausencia de pregunta.');
mc('tipos','Elige la transformación INTERROGATIVA de «Es joven».',['¡Es muy joven!','¿Es joven?','Ojalá sea joven.'],1,'La interrogativa convierte la información en una pregunta; en español lleva ¿ al principio y ? al final.','Mantén el contenido y cambia la intención para preguntar.','Una pregunta directa necesita signos de apertura y cierre.');
mc('tipos','Elige la transformación EXCLAMATIVA de «Es una fotografía sensacional».',['¡Es una fotografía sensacional!','¿Es una fotografía sensacional?','Quizá sea una fotografía sensacional.'],0,'Con ¡! la frase expresa admiración o entusiasmo.','Fíjate en la intención: emoción, no duda ni pregunta.','Tiene que sonar emocionada.');
mc('tipos','¿Cuál expresa una duda y no un deseo?',['Ojalá pueda venir.','Que tengas buena suerte.','Puede que llegue tarde.'],2,'«Puede que» introduce una posibilidad incierta; «ojalá» y «que tengas» expresan deseos.','Dubitativa = no estamos seguros de que ocurra.','Busca incertidumbre, no una esperanza.');
mc('tipos','¿Cuál es una interrogativa indirecta?',['¿Cómo te llamas?','Me pregunto dónde está mi lápiz.','¡He perdido mi lápiz!'],1,'En «Me pregunto dónde está mi lápiz» se expresa una pregunta integrada en otra oración, sin signos ¿?.','Busca una pregunta incorporada a «me pregunto» o «no sé».','No todas las interrogativas llevan signos visibles.');

// SIGNOS DE PUNTUACIÓN: mismo repertorio de 8 signos del material.
const signOptions=['Punto (.)','Coma (,)','Punto y coma (;)','Dos puntos (:)','Puntos suspensivos (…)','Comillas (« »)','Paréntesis ( )','Raya (—)'];
function signQuestion(p,correct,why,how,hint=''){mc('puntuacion',p,signOptions,correct,why,how,hint,{family:'signs'});}
signQuestion('¿Qué signo usamos para cerrar una oración que ya ha terminado?',0,'El punto indica que una oración ha terminado.','Cuando la idea está completa, coloca un punto y empieza otra oración.');
signQuestion('¿Qué signo separa los elementos en «Compré pan, leche, fruta y queso»?',1,'Las comas separan los elementos de una enumeración sencilla.','Identifica cada elemento de la lista y coloca una coma entre ellos.');
signQuestion('¿Qué signo introduce una enumeración, como «Traigo tres cosas: agua, fruta y pan»?',3,'Los dos puntos anuncian lo que viene después: en este caso, una enumeración.','Lee el comienzo: «tres cosas» prepara la lista.','Aparece antes de la lista.');
signQuestion('¿Qué signo indica que una idea queda incompleta, como «No sé…»?',4,'Los puntos suspensivos indican duda, pausa o una idea sin terminar.','Si el hablante se detiene sin completar la frase, usa tres puntos.','Se forma con tres puntos.');
signQuestion('¿Qué signo se emplea para introducir lo que dice un personaje en un diálogo?',7,'La raya (—) abre la intervención de un personaje.','Al iniciar una nueva intervención, escribe una raya larga antes de las palabras del personaje.','No es un guion corto (-).');
signQuestion('¿Qué signo permite añadir «(el planeta rojo)» detrás de «Marte»?',6,'Los paréntesis encierran información complementaria o aclaratoria.','Deja el dato principal fuera y coloca la aclaración dentro de ( ).');
signQuestion('¿Qué signo usarías para citar exactamente «Muy bien hecho»?',5,'Las comillas delimitan las palabras dichas o escritas literalmente.','Abre las comillas antes de la cita y ciérralas después.');
signQuestion('¿Qué signo separa ciudades y países en «Madrid, España; Lisboa, Portugal; París, Francia»?',2,'El punto y coma separa elementos de una enumeración compleja que ya contiene comas.','Como cada pareja ciudad-país lleva coma, distingue los grupos mayores con punto y coma.');
mc('puntuacion','Completa: «El material es el siguiente__ lápiz, goma y regla».',['.',';',':',','],2,'Los dos puntos introducen la enumeración después de una frase que la anuncia.','«El material es el siguiente» prepara lo que se va a enumerar.','Piensa en dos puntos antes de una lista.');
mc('puntuacion','¿Cuál está puntuada correctamente?',['Me gustan: el queso el pan y la fruta.','Me gustan el queso, el pan y la fruta.','Me gustan el queso; el pan; y la fruta.'],1,'En una enumeración sencilla, las comas separan los elementos y la conjunción «y» puede unir los dos últimos.','Cuenta los elementos y separa los intermedios con comas.','No es una lista compleja.');
mc('puntuacion','¿Qué opción utiliza correctamente los puntos suspensivos?',['No sé... quizá tengas razón.','No sé,,,, quizá tengas razón.','No sé;; quizá tengas razón.'],0,'Los tres puntos expresan la vacilación antes de continuar la idea.','Una pausa de duda se puede representar con puntos suspensivos; no con varias comas o punto y coma.');
mc('puntuacion','¿Cuál es un diálogo escrito con raya?',['«Hola», dijo Sonia.','—Hola —dijo Sonia.','(Hola) dijo Sonia.'],1,'La raya introduce la intervención «Hola» y marca la intervención del narrador.','En un diálogo se usa raya larga — para señalar quién habla.');
mc('puntuacion','¿Dónde pondrías paréntesis?',['La Tierra planeta en el que vivimos gira alrededor del Sol.','La Tierra (planeta en el que vivimos) gira alrededor del Sol.','La Tierra; planeta en el que vivimos; gira alrededor del Sol.'],1,'«Planeta en el que vivimos» es una aclaración adicional y puede encerrarse entre paréntesis.','La oración principal debe poder leerse sin la aclaración.');
mc('puntuacion','¿Qué frase utiliza las comillas para reproducir palabras exactas?',['La profesora dijo: «Abrid los libros».','La profesora dijo (Abrid los libros).','La profesora dijo; Abrid los libros.'],0,'Las palabras literales de la profesora van entre comillas y los dos puntos las anuncian.','Primero introduce quién habló; después escribe lo que dijo exactamente entre comillas.');
mc('puntuacion','¿Cuál de estas oraciones está correctamente separada con punto?',['Hoy hace sol Mañana quizá llueva.','Hoy hace sol. Mañana quizá llueva.','Hoy hace. sol mañana quizá llueva.'],1,'Cada oración comunica una idea completa y lleva su punto.','Busca dónde acaba la primera idea: «Hoy hace sol».');
mc('puntuacion','¿Por qué se usa punto y coma aquí? «En el equipo hay Ana, de sexto; Pablo, de quinto; y Lía, de cuarto».',['Porque cada nombre debe ir entre comillas.','Porque separa grupos que ya contienen comas.','Porque abre una pregunta.'],1,'Los datos de cada persona están separados por comas internas; el punto y coma marca los límites entre grupos.','Observa que cada grupo tiene la estructura «nombre, de curso».','Hay comas dentro de la lista.');
mc('puntuacion','Elige la oración que anuncia bien una explicación.',['No fui al parque: estaba lloviendo.','No fui al parque, estaba: lloviendo.','No fui: al parque estaba lloviendo.'],0,'Los dos puntos pueden introducir una explicación de la idea anterior.','La segunda parte «estaba lloviendo» explica la primera.','El signo va justo antes de la explicación.');
mc('puntuacion','¿Qué opción sitúa bien la raya en el diálogo?',['—¿Vienes conmigo? —preguntó Ana.','¿Vienes conmigo?; preguntó Ana.','(¿Vienes conmigo?) preguntó Ana.'],0,'La raya abre la intervención y también separa las palabras del narrador.','Marca dónde habla el personaje y dónde interviene el narrador.');
mc('puntuacion','En «Julia (mi prima) vive en Burgos», ¿qué función tienen los paréntesis?',['Marcar una lista.','Introducir un diálogo.','Añadir información aclaratoria.'],2,'«Mi prima» añade un dato sobre Julia, pero la oración se entiende sin él.','Quita mentalmente la parte entre paréntesis: «Julia vive en Burgos».');
mc('puntuacion','¿Cuál es la forma correcta de cerrar dos ideas completas?',['El gato duerme. El perro juega.','El gato duerme, El perro juega','El gato duerme: El perro juega;'],0,'Son dos oraciones completas, cada una con su punto final.','Cuando termina una idea, pon punto; inicia la siguiente con mayúscula.');
mc('puntuacion','En «¡Qué misterio...!», ¿para qué se usan los puntos suspensivos?',['Para separar una lista de países.','Para crear una pausa o dejar la idea en suspense.','Para indicar quién habla.'],1,'Los puntos suspensivos crean aquí una pausa expresiva y dejan la emoción en suspensión.','Conecta el signo con la pausa o el suspense, no con una enumeración.');

// B/V: mismas familias de reglas y excepciones de los apuntes.
function bvWord(text,letter,why,how,hint=''){mc('bv',`Completa con B o V: «${text}»`,['B','V'],letter==='b'?0:1,why,how,hint,{family:'bv',displayAnswer:text.replace('_',letter),isLetter:true});}
bvWord('_ufanda','b','«Bufanda» empieza por bu-, y las palabras que empiezan por bu-, bur- y bus- se escriben con B.','Busca las primeras letras de la palabra: bu- → B.','Empieza por bu-.');
bvWord('_urbuja','b','«Burbuja» empieza por bur-, una de las sílabas de la regla de la B.','Compara con la familia bu-, bur-, bus- de la ficha.','Empieza por bur-.');
bvWord('_uscar','b','«Buscar» empieza por bus-, así que se escribe con B.','Identifica la sílaba inicial bus- y aplica la regla.','Empieza por bus-.');
bvWord('escri_ir','b','«Escribir» termina en -bir. La norma usa B, salvo hervir, servir y vivir.','Localiza la terminación del infinitivo y revisa si es una excepción.','¿Termina en -bir?');
bvWord('reci_ir','b','«Recibir» termina en -bir y no es una de las tres excepciones de la regla.','Comprueba -bir y descarta hervir, servir y vivir.','Es un verbo terminado en -bir.');
bvWord('ser_ir','v','«Servir» es una excepción de los infinitivos acabados en -bir: se escribe con V.','Memoriza las tres excepciones: hervir, servir y vivir.','Pertenece a las tres excepciones.');
bvWord('vi_ir','v','«Vivir» lleva V: está entre las excepciones a la regla -bir.','Recuerda «hervir, servir y vivir», todas con V.','Es una excepción.');
bvWord('her_ir','v','«Hervir» es una excepción a la regla de los infinitivos terminados en -bir.','Repite la lista de excepciones: hervir, servir, vivir.','Es una de las tres excepciones.');
bvWord('amabilidad'.replace('b','_'),'b','«Amabilidad» termina en -bilidad, una terminación que suele escribirse con B.','Busca -bilidad al final y recuerda la excepción «movilidad».','Termina en -bilidad.');
bvWord('responsa_ilidad','b','«Responsabilidad» acaba en -bilidad, por eso lleva B.','Aplica la terminación -bilidad; la excepción señalada es movilidad.','Fíjate en la terminación.');
bvWord('mo_ilidad','v','«Movilidad» es la excepción de la ficha a la regla general de -bilidad.','Comprueba primero la regla y después si el término es «movilidad».','Es una excepción importante.');
bvWord('canta_a','b','«Cantaba» es pretérito imperfecto de «cantar», un verbo de la primera conjugación (-ar).','En las formas del imperfecto de verbos en -ar aparece -aba con B.','Cantar → cantaba.');
bvWord('jugá_amos','b','«Jugábamos» es pretérito imperfecto de «jugar»: la terminación -ábamos se escribe con B.','Reconoce el verbo jugar (-ar) y la terminación -ábamos.','Busca -ábamos.');
bvWord('camina_ais','b','«Caminabais» se escribe con B por ser imperfecto del verbo caminar (-ar).','Las formas del imperfecto en -aba, -abas, -ábamos, -abais, -aban se escriben con B.','Es imperfecto de un verbo en -ar.');
bvWord('sua_e','v','«Suave» lleva V por la terminación -ave en un adjetivo llano.','Comprueba el final: -ave pertenece a la serie -ava, -ave, -avo, -eva, -eve, -evo, -ivo, -iva.','Es un adjetivo acabado en -ave.');
bvWord('acti_o','v','«Activo» es un adjetivo llano terminado en -ivo: se escribe con V.','Identifica el sufijo -ivo, una de las terminaciones con V de la ficha.','Termina en -ivo.');
bvWord('creati_a','v','«Creativa» es un adjetivo llano acabado en -iva y lleva V.','Busca el sufijo -iva entre las terminaciones de adjetivos con V.','Termina en -iva.');
bvWord('nue_a','v','«Nueva» es un adjetivo llano terminado en -eva: lleva V.','Identifica el final -eva.','Termina en -eva.');
bvWord('octa_o','v','«Octavo» es un adjetivo llano acabado en -avo y lleva V.','Reconoce -avo en la lista de terminaciones de adjetivos.','Termina en -avo.');
bvWord('estu_e','v','«Estuve» es una forma de «estar»: su infinitivo no contiene B ni V, y se escribe con V.','Piensa en el infinitivo «estar» y en la regla de las formas verbales con V.','Infinitivo: estar.');
bvWord('andu_e','v','«Anduve» procede de «andar», cuyo infinitivo no lleva ni B ni V.','La forma verbal «anduve» usa V; no es el imperfecto en -aba.','Infinitivo: andar.');
bvWord('tu_e','v','«Tuve» viene de «tener», que no contiene B ni V en el infinitivo.','En pretérito de tener, «tuve» lleva V. No lo confundas con «tenía».','Infinitivo: tener.');
fill('bv','Completa el pretérito imperfecto: «Antes, yo _____ (cantar) en el coro».','cantaba','El pretérito imperfecto de «cantar» en primera persona es «cantaba», con B.','Conjuga yo + cantar en pasado habitual: cantaba. La terminación -aba lleva B.','Empieza por canta-.');
fill('bv','Completa el pretérito imperfecto: «Cuando éramos pequeños, nosotros _____ (jugar) en el patio».','jugábamos','«Jugábamos» es imperfecto de jugar, y su terminación -ábamos lleva B.','Sujeto nosotros → terminación -ábamos. Recuerda también la tilde.','Escribe jugar en imperfecto, primera persona plural.',['jugabamos']);
fill('bv','Forma un adjetivo terminado en -ivo a partir de «competir»: un equipo _____».','competitivo','«Competitivo» es un adjetivo terminado en -ivo, por eso lleva V.','Parte de «competir», añade la forma adjetiva «competitivo» y comprueba -ivo.','Termina en -tivo.');
fill('bv','Forma un adjetivo femenino a partir de «crear»: una persona _____».','creativa','«Creativa» termina en -iva, por lo que se escribe con V.','Transforma crear → creativo → creativa (concuerda con «persona»).','Termina en -iva.');
mc('bv','¿Cuál es la única excepción de -bilidad que destaca la ficha?',['Amabilidad','Movilidad','Responsabilidad'],1,'«Movilidad» se escribe con V; «amabilidad» y «responsabilidad» siguen la regla general con B.','Primero recuerda -bilidad → B; después memoriza movilidad → V.');
mc('bv','¿Qué grupo incluye las tres excepciones de los infinitivos en -bir?',['Hervir, servir, vivir.','Escribir, recibir, subir.','Buscar, burbuja, bufanda.'],0,'Los apuntes señalan «hervir, servir, vivir» como las tres excepciones con V.','Aprende las tres juntas, como una pequeña lista.');
mc('bv','¿Qué forma está bien escrita?',['Cantaba','Cantava','Cántava'],0,'«Cantaba» es la forma correcta: en el imperfecto de «cantar» la terminación es -aba, con B.','Busca las terminaciones de verbos en -ar: -aba, -abas, -ábamos, -abais, -aban.');
mc('bv','¿Qué explicación justifica la V de «anduve»?',['Empieza por bur-.','Termina en -bilidad.','Viene de «andar», cuyo infinitivo no contiene B ni V.'],2,'«Anduve» es una forma del verbo «andar», sin B ni V en infinitivo; en esta forma verbal se utiliza V.','Compara forma conjugada e infinitivo, y comprueba que no sea una terminación -aba.');
mc('bv','¿Qué pareja está escrita correctamente?',['amavilidad y nueba','amabilidad y nueva','amavilidad y nueva'],1,'«Amabilidad» acaba en -bilidad y lleva B; «nueva» es un adjetivo llano terminado en -eva y lleva V.','Aplica una regla distinta a cada palabra: -bilidad con B, -eva con V.');

// Tilde diacrítica: elegir la grafía por la función y el significado.
mc('diacritica','¿Qué frase distingue bien el artículo y el pronombre?',['El libro es para él.','Él libro es para el.','El libro es para el.'],0,'«El» acompaña al nombre «libro» y es artículo; «él» sustituye a una persona y es pronombre.','Busca el nombre al que acompaña cada palabra.','Una de las dos palabras sustituye a una persona.');
mc('diacritica','Completa: «Espero que me ___ una respuesta».',['de','dé','él'],1,'«Dé» es una forma del verbo dar y lleva tilde.','Prueba a cambiarlo por «entregue»: espero que me dé una respuesta.','Es una forma del verbo dar.');
mc('diacritica','¿En qué oración «mas» significa «pero»?',['Quiero más tiempo.','Lo intenté, mas no lo conseguí.','Añade una cucharada más.'],1,'«Mas» sin tilde equivale a «pero»; «más» con tilde expresa cantidad o comparación.','Sustituye la palabra por «pero» y comprueba si la frase conserva el sentido.','Busca la frase en la que encaja «pero».');
mc('diacritica','Elige la frase correcta.',['Mi lo guardé para.','Lo guardé para mi.','Lo guardé para mí.'],2,'Después de la preposición «para», «mí» es un pronombre y lleva tilde.','Pregunta «¿para quién?»: si sustituye a una persona, es el pronombre mí.','Es un pronombre después de «para».');
mc('diacritica','Completa: «No ___ dónde dejé la libreta».',['se','sé','sè'],1,'«Sé» es una forma del verbo saber y lleva tilde.','La frase expresa que no conozco el lugar: verbo saber.','Equivale a «no conozco».');
mc('diacritica','¿Qué opción expresa una condición?',['Sí vienes, avísame.','Si vienes, avísame.','Si, vienes avísame.'],1,'«Si» introduce una condición y se escribe sin tilde.','La primera parte plantea qué ocurrirá en caso de que vengas.','¿Equivale a «en caso de que»?');
mc('diacritica','¿Qué oración usa correctamente «te» y «té»?',['Te preparo un té.','Té preparo un te.','Te preparo un te.'],0,'«Te» es un pronombre; «té» es la bebida.','Identifica la acción y el nombre de la bebida.','La bebida lleva tilde.');
mc('diacritica','Elige la frase con «tú» y «tu» bien diferenciados.',['Tú has dejado tu estuche.','Tu has dejado tú estuche.','Tú has dejado tú estuche.'],0,'«Tú» es el pronombre que realiza la acción; «tu» acompaña al nombre «estuche».','Pregunta quién ha dejado el estuche y qué palabra indica posesión.','Una palabra acompaña a «estuche».');
mc('diacritica','Completa: «___ no ha empezado la película».',['Aun','Aún','Aunqué'],1,'«Aún» equivale a «todavía» y lleva tilde.','Prueba: «Todavía no ha empezado la película».','Sustitúyelo por «todavía».');
mc('diacritica','¿Qué frase usa «aun» con el sentido de «incluso»?',['Aun los más pequeños participaron.','Aún no han llegado los invitados.','Aún tengo que estudiar.'],0,'En «Aun los más pequeños», «aun» significa «incluso» y se escribe sin tilde.','Cambia «aun» por «incluso» y lee la oración.','Equivale a «incluso».');
mc('diacritica','¿Qué frase lleva «sí» porque expresa afirmación?',['No sé si vendrá.','Me preguntó si quería agua.','Sí, quiero un poco.'],2,'«Sí» con tilde es una respuesta afirmativa; «si» sin tilde introduce una condición o una pregunta indirecta.','Busca la respuesta afirmativa, no una condición.','Es una respuesta afirmativa.');
mc('diacritica','¿Cuál está escrita correctamente?',['Sé paciente y escucha.','Se paciente y escucha.','Sé paciénte y escucha.'],0,'«Sé» lleva tilde cuando es el imperativo del verbo ser.','Prueba a sustituirlo por «ten paciencia»: es una forma del verbo ser.','Es una orden del verbo ser.');
mc('diacritica','¿Qué oración usa «sí» como pronombre?',['Ella confía en sí misma.','Si estudias, lo lograrás.','No sé la respuesta.'],0,'En «en sí misma», «sí» es un pronombre precedido de preposición y lleva tilde.','La palabra se refiere a la misma persona: confía en ella misma.','Va después de una preposición y se refiere a la persona.');
fill('diacritica','Completa: «No ___ si podré llegar a tiempo».','sé','«Sé» es del verbo saber: no sé si podré llegar.','Pregúntate si significa «conozco»; aquí sí.','Es el verbo saber.');
fill('diacritica','Completa: «El mensaje era para ___».','él','«Él» sustituye a una persona y lleva tilde.','Después de «para» aparece un pronombre.','Es un pronombre personal.');
fill('diacritica','Completa: «Ojalá el director me ___ permiso».','dé','«Dé» es del verbo dar y lleva tilde.','Equivale a «conceda permiso».','Forma del verbo dar.');
fill('diacritica','Completa: «___ no han abierto la biblioteca» (todavía).','Aún','Como equivale a «todavía», se escribe aún con tilde.','Usa la palabra que aparece entre paréntesis.','Sustitúyelo por «todavía».');
fill('diacritica','Completa: «___ con mucho ruido, pudimos escuchar» (incluso).','Aun','Con el sentido de «incluso», aun se escribe sin tilde.','Usa la palabra que aparece entre paréntesis.','Sustitúyelo por «incluso».');
fill('diacritica','Escribe la frase con las tildes necesarias: «tu sabes que el resultado depende de ti»','Tú sabes que el resultado depende de ti.','«Tú» es pronombre y «el» es artículo; «ti» nunca lleva tilde.','Señala quién sabe (tú), distingue el artículo delante de «resultado» y recuerda que ti va sin tilde.','Busca el pronombre inicial y el artículo; «ti» no se tilda.',['Tú sabes que el resultado depende de ti']);

const STORAGE_KEY='academia_palabras_v1';
const DRAFT_KEY='academia_palabras_redaccion_v1';
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const esc = s => String(s??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle = a => [...a].sort(()=>Math.random()-.5);
const topicQuestions = id => QUESTIONS.filter(q=>q.topic===id);
function loadJSON(key,fallback){try{let s=localStorage.getItem(key);return s?JSON.parse(s):fallback;}catch(e){return fallback;}}
function saveJSON(key,obj){try{localStorage.setItem(key,JSON.stringify(obj));}catch(e){/* La web sigue funcionando aunque el navegador bloquee el almacenamiento. */}}
function blankData(){return {xp:0,answered:0,correct:0,streak:0,bestStreak:0,correctIds:[],missedIds:[],visited:[],exams:0,bestExam:0,stats:Object.fromEntries(TOPICS.map(t=>[t.id,{answered:0,correct:0}]))};}
let data=Object.assign(blankData(),loadJSON(STORAGE_KEY,{}));
if(!data.stats) data.stats=blankData().stats;
for(const t of TOPICS) if(!data.stats[t.id])data.stats[t.id]={answered:0,correct:0};
let draft=loadJSON(DRAFT_KEY,{title:'',intro:'',near:'',middle:'',far:'',ending:'',checks:[]});
let selectedLesson='descripcion';
let practiceConfig={topic:'mezcla',count:8,onlyMissed:false};
let practiceSession=null, examSession=null, toastTimeout;
const signMeaning=['finaliza una oración','separa elementos o aclaraciones','separa grupos complejos o ideas relacionadas','anuncia lista, cita o explicación','indica pausa, duda o frase inacabada','encierra palabras textuales','añade una aclaración','introduce intervenciones de un diálogo'];
const percent=(a,b)=>b?Math.round(100*a/b):0;
const scoreLabel=q=>q.isLetter?q.displayAnswer:(q.type==='choice'?q.options[q.answer]:q.answer);
const valueLabel=(q,v)=>v===null||v===undefined||v===''?'Sin respuesta':q.type==='choice'?(q.options[Number(v)]??'Sin respuesta'):String(v);
function isCorrect(q,value){if(q.type==='choice')return Number(value)===q.answer;const v=String(value??'').trim().toLocaleLowerCase('es').normalize('NFC').replace(/\s+/g,' ');return [q.answer,...(q.alternates||[])].some(a=>String(a).trim().toLocaleLowerCase('es').normalize('NFC')===v);}
function persist(){saveJSON(STORAGE_KEY,data);$('#topXP').textContent=data.xp;}
function markAnswer(q,correct,hinted=false){data.answered++;data.stats[q.topic].answered++;if(correct){data.correct++;data.stats[q.topic].correct++;data.streak++;data.bestStreak=Math.max(data.bestStreak,data.streak);if(!data.correctIds.includes(q.id))data.correctIds.push(q.id);data.missedIds=data.missedIds.filter(x=>x!==q.id);data.xp+=hinted?5:10;}else{data.streak=0;if(!data.missedIds.includes(q.id))data.missedIds.push(q.id);}persist();}
function toast(msg){const node=$('#toast');node.textContent=msg;node.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>node.classList.remove('show'),2200);}
function goPage(id){if(!['inicio','aprender','practicar','examen','progreso'].includes(id))id='inicio';$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${id}`));$$('.nav-btn').forEach(x=>{let active=x.dataset.page===id;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});if(location.hash.slice(1)!==id)location.hash=id;window.scrollTo({top:0,behavior:'instant'});if(id==='inicio')renderHome();if(id==='aprender')renderLesson();if(id==='practicar')renderPractice();if(id==='examen')renderExam();if(id==='progreso')renderProgress();}
function linkButtons(){for(const b of $$('[data-page]'))b.addEventListener('click',()=>goPage(b.dataset.page));$$('[data-nav]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();goPage('inicio');}));$('#homePractice').addEventListener('click',()=>goPage('practicar'));$('#homeLearn').addEventListener('click',()=>goPage('aprender'));$('#homeExam').addEventListener('click',()=>goPage('examen'));window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(['inicio','aprender','practicar','examen','progreso'].includes(id))goPage(id);});}
function renderHome(){
 const boxes=[['🌟',data.correct,'Respuestas acertadas'],['⚡',data.xp,'Puntos ganados'],['🔥',data.streak,'Aciertos seguidos']];
 $('#homeStats').innerHTML=boxes.map(([icon,num,label])=>`<div class="stat-card"><span class="stat-icon">${icon}</span><div><div class="stat-main">${num}</div><div class="stat-label">${label}</div></div></div>`).join('');
 $('#worldGrid').innerHTML=TOPICS.map((t,i)=>{let s=data.stats[t.id];return `<button type="button" class="world-card" data-world="${t.id}" style="--accent:${t.color}"><div class="world-number"><span>MUNDO ${String(i+1).padStart(2,'0')}</span><span>${s.answered?percent(s.correct,s.answered)+'%':'NUEVO'}</span></div><span class="world-emoji">${t.emoji}</span><h3>${esc(t.label)}</h3><p>${esc(t.description)}</p><div class="world-foot">Explorar mundo →</div></button>`;}).join('');
 $$('[data-world]').forEach(el=>el.addEventListener('click',()=>{selectedLesson=el.dataset.world;goPage('aprender');}));
}
function renderLesson(){
 const topic=T(selectedLesson),lesson=LESSONS[selectedLesson];if(!data.visited.includes(selectedLesson)){data.visited.push(selectedLesson);persist();}
 $('#lessonTabs').innerHTML=TOPICS.map(t=>`<button type="button" role="tab" aria-selected="${t.id===selectedLesson}" class="topic-tab ${t.id===selectedLesson?'active':''}" data-lesson="${t.id}">${t.emoji} ${esc(t.short)}</button>`).join('');
 $('#lessonContent').innerHTML=`<div class="lesson-layout"><div><div class="lesson-top"><span>${topic.emoji}</span><div><div class="eyebrow">${esc(topic.tag)}</div><h2>${esc(topic.label)}</h2><p>${esc(lesson.intro)}</p></div></div>${lesson.sections.map((section,i)=>`<article class="lesson-section"><h3><span aria-hidden="true">${['✨','📌','🧩','🔍','💡'][i%5]}</span> ${section.title}</h3>${section.body}</article>`).join('')}</div><aside class="sidebar-sticky"><div class="tip-card"><h3>💡 TRUCO DE EXPLORADORA</h3><p>${esc(lesson.tip)}</p></div><div class="lesson-actions"><div class="eyebrow">SIGUIENTE PASO</div><h3>¿Lo tienes claro?</h3><p>Pon a prueba lo aprendido con preguntas sobre este tema.</p><button type="button" class="btn primary block" id="lessonPractice">🎮 Practicar este tema</button>${selectedLesson==='descripcion'?'<button type="button" class="btn outline block" id="toWriting">✍️ Taller de descripción</button>':''}</div></aside></div>${selectedLesson==='descripcion'?'<div id="writingMount"></div>':''}`;
 $$('[data-lesson]').forEach(el=>el.addEventListener('click',()=>{selectedLesson=el.dataset.lesson;renderLesson();}));
 $('#lessonPractice').addEventListener('click',()=>{practiceConfig.topic=selectedLesson;practiceSession=null;goPage('practicar');});
 if(selectedLesson==='descripcion'){renderWritingWorkshop();$('#toWriting').addEventListener('click',()=>$('#writingMount').scrollIntoView({behavior:'smooth'}));}
}
const WRITING_CHECKS=['He puesto un título claro y relacionado con el paisaje.','La introducción presenta una visión general.','Mi descripción es precisa y no inventa lo observado.','He utilizado adjetivos.','He seguido el orden: primer plano, segundo plano y fondo.','El cierre expresa alguna sensación o impresión.','Las frases están bien construidas y se entienden.','He utilizado conectores espaciales.','He revisado la ortografía y la puntuación.'];
function writingText(){return [draft.title,draft.intro,draft.near,draft.middle,draft.far,draft.ending].filter(Boolean).join('\n\n');}
function renderWritingWorkshop(){
 $('#writingMount').innerHTML=`<div class="writing" id="writingWorkshop"><div class="eyebrow">✍️ EL TALLER DE ESCRITURA</div><h2>Tu propia descripción de paisaje</h2><p>Sigue el mismo orden de la ficha del cole. El borrador se conserva en este navegador.</p><details class="example worked-example"><summary>📜 Ver un ejemplo de descripción resuelta</summary><p class="microcopy">Ejemplo original siguiendo la estructura de la ficha de clase.</p><p><strong>Título:</strong> Una playa al amanecer</p><p><strong>Introducción:</strong> Frente a mí se extiende una playa tranquila. El mar está en calma y el cielo comienza a iluminarse.</p><p><strong>Primer plano:</strong> A mis pies, la arena dorada está húmeda y se ven pequeñas conchas blancas.</p><p><strong>Segundo plano:</strong> A la derecha hay unas palmeras altas que se mueven suavemente con el viento.</p><p><strong>Fondo:</strong> A lo lejos se distinguen las montañas azuladas y unas nubes rosadas sobre el horizonte.</p><p><strong>Cierre:</strong> Escucho las olas y siento la brisa fresca en la cara. Este paisaje me transmite mucha paz.</p></details><div class="writing-fields">${[
  ['title','Título','Pon un título breve y relacionado','input'],
  ['intro','Introducción · visión general','¿Qué paisaje observas? ¿Cómo es en conjunto?','textarea'],
  ['near','Primer plano · cerca','¿Qué hay cerca? Añade detalles y adjetivos.','textarea'],
  ['middle','Segundo plano · zona central','¿Qué hay detrás o a los lados?','textarea'],
  ['far','Fondo · lejos','¿Qué aparece en el horizonte?','textarea'],
  ['ending','Cierre · sensaciones','¿Qué ves, oyes, hueles o sientes allí?','textarea']
 ].map(([id,label,help,type])=>`<div class="field ${id==='intro'||id==='ending'?'wide':''}"><label for="w-${id}">${label}</label><small>${help}</small>${type==='input'?`<input id="w-${id}" data-draft="${id}" maxlength="130" value="${esc(draft[id])}" placeholder="Escribe aquí…">`:`<textarea id="w-${id}" data-draft="${id}" rows="3" placeholder="Escribe aquí…">${esc(draft[id])}</textarea>`}</div>`).join('')}</div><h3>🪞 Vista previa de mi texto</h3><div class="preview-text" id="writingPreview">${esc(writingText()||'Tu descripción aparecerá aquí a medida que escribas…')}</div><div class="inline-controls"><h3>✅ Mi rúbrica de autoevaluación</h3><span class="microcopy">La misma que aparece en clase</span></div><div class="checklist">${WRITING_CHECKS.map((item,i)=>`<label><input type="checkbox" data-check="${i}" ${draft.checks.includes(i)?'checked':''}><span>${esc(item)}</span></label>`).join('')}</div><div class="writer-score" id="writingScore"></div><div class="writing-actions" style="margin-top:16px"><button class="btn primary" type="button" id="checkWriting">🔎 Revisar mi estructura</button><button class="btn outline" type="button" id="copyWriting">📋 Copiar mi texto</button><button class="btn ghost" type="button" id="clearWriting">Borrar borrador</button></div><p class="microcopy">La web comprueba si has completado las partes y permite autoevaluarte, pero no califica automáticamente la creatividad ni garantiza que la ortografía sea correcta.</p></div>`;
 $$('[data-draft]').forEach(el=>el.addEventListener('input',()=>{draft[el.dataset.draft]=el.value;saveJSON(DRAFT_KEY,draft);$('#writingPreview').textContent=writingText()||'Tu descripción aparecerá aquí a medida que escribas…';}));
 $$('[data-check]').forEach(el=>el.addEventListener('change',()=>{let id=Number(el.dataset.check);draft.checks=el.checked?[...new Set([...draft.checks,id])]:draft.checks.filter(x=>x!==id);saveJSON(DRAFT_KEY,draft);updateWritingScore(false);}));
 $('#checkWriting').addEventListener('click',()=>updateWritingScore(true));
 $('#copyWriting').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(writingText());toast('📋 ¡Texto copiado!');}catch(e){const ta=document.createElement('textarea');ta.value=writingText();document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('📋 Texto preparado para copiar');}});
 $('#clearWriting').addEventListener('click',()=>{if(!confirm('¿Seguro que quieres borrar todo el borrador de descripción?'))return;draft={title:'',intro:'',near:'',middle:'',far:'',ending:'',checks:[]};saveJSON(DRAFT_KEY,draft);renderWritingWorkshop();});
 updateWritingScore(false);
}
function updateWritingScore(detailed){let used=['title','intro','near','middle','far','ending'].filter(k=>draft[k].trim()).length;let checks=draft.checks.length;let msg=`<strong>${used}/6 partes escritas</strong> · ${checks}/9 casillas de revisión marcadas.`;if(detailed){let missing=['title','intro','near','middle','far','ending'].filter(k=>!draft[k].trim());if(missing.length)msg+=`<p>Antes de terminar, te faltan ${missing.length} ${missing.length===1?'parte':'partes'}: ${missing.map(x=>({title:'título',intro:'introducción',near:'primer plano',middle:'segundo plano',far:'fondo',ending:'cierre'}[x])).join(', ')}.</p>`;else msg+='<p>¡La estructura está completa! Ahora revisa si hay adjetivos, conectores y detalles de los sentidos; luego lee la rúbrica con atención.</p>';if(used===6&&checks===9)toast('✍️ ¡Rúbrica completada!');}$('#writingScore').innerHTML=msg;}
function renderPractice(){if(practiceSession)renderPracticePlay();else renderPracticeSetup();}
function renderPracticeSetup(){
 const hasMissed=data.missedIds.some(id=>QUESTIONS.some(q=>q.id===id));
 $('#practiceContent').innerHTML=`<div class="setup-panel"><div class="eyebrow">PASO 1 DE 2</div><h2>Elige un mundo para entrenar</h2><p>Puedes mezclar todos los temas o concentrarte en uno.</p><div class="topic-selector"><button class="topic-choice ${practiceConfig.topic==='mezcla'?'active':''}" data-pick-topic="mezcla"><span>🌌</span>Mezcla total</button>${TOPICS.map(t=>`<button class="topic-choice ${practiceConfig.topic===t.id?'active':''}" data-pick-topic="${t.id}"><span>${t.emoji}</span>${esc(t.short)}</button>`).join('')}</div><div class="option-heading">PASO 2 DE 2 · DURACIÓN DEL RETO</div><div class="options-row">${[5,8,15].map(n=>`<button class="chip-btn ${practiceConfig.count===n?'active':''}" data-pick-count="${n}">${n} preguntas</button>`).join('')}</div><div class="options-row"><button class="chip-btn ${practiceConfig.onlyMissed?'active':''}" id="practiceMissed" ${hasMissed?'':'disabled'}>🔁 Repasar solo mis fallos ${data.missedIds.length?'('+data.missedIds.length+')':''}</button></div><div class="inline-controls"><p class="microcopy">+10 XP por acierto · +5 si usas una pista · Explicación después de responder</p><button class="btn primary" id="startPractice">🚀 ¡Comenzar reto!</button></div></div>`;
 $$('[data-pick-topic]').forEach(el=>el.addEventListener('click',()=>{practiceConfig.topic=el.dataset.pickTopic;renderPracticeSetup();}));
 $$('[data-pick-count]').forEach(el=>el.addEventListener('click',()=>{practiceConfig.count=Number(el.dataset.pickCount);renderPracticeSetup();}));
 $('#practiceMissed').addEventListener('click',()=>{practiceConfig.onlyMissed=!practiceConfig.onlyMissed;renderPracticeSetup();});
 $('#startPractice').addEventListener('click',startPractice);
}
function startPractice(){let pool=QUESTIONS.filter(q=>(practiceConfig.topic==='mezcla'||q.topic===practiceConfig.topic)&&(!practiceConfig.onlyMissed||data.missedIds.includes(q.id)));if(!pool.length){toast('No hay fallos de ese tema; cambia el filtro.');return;}const questions=shuffle(pool).slice(0,practiceConfig.count);practiceSession={questions,index:0,selected:null,input:'',answered:false,hinted:false,result:null,correct:0};renderPracticePlay();}
function answerWidget(q,selected,locked=false){
 if(q.type==='fill')return `<label class="microcopy" for="freeAnswer">Escribe la palabra o expresión que falta:</label><input id="freeAnswer" class="answer-input" autocomplete="off" spellcheck="false" ${locked?'disabled':''} placeholder="Tu respuesta…" value="${esc(selected??'')}"><p class="microcopy">Escribe la palabra completa. Respeta B y V.</p>`;
 return `<div role="group" aria-label="Opciones de respuesta">${q.options.map((a,i)=>`<button type="button" class="choice-btn ${selected===i?'selected':''} ${locked&&i===q.answer?'correct':''} ${locked&&i===selected&&selected!==q.answer?'wrong':''}" data-answer-choice="${i}" ${locked?'disabled':''} aria-pressed="${selected===i}"><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${esc(a)}</span></button>`).join('')}</div>`;
}
function wrongContrast(q,value){
 if(value===null||value===undefined||value==='')return 'No has seleccionado una respuesta. No pasa nada: mira qué pista te permitía resolverla.';
 if(q.family==='types'&&q.type==='choice'){const chosen=q.options[Number(value)].toLowerCase(),correct=q.options[q.answer].toLowerCase();return `Elegiste «${chosen}», que ${typesWhy[chosen]}, pero aquí la intención es «${correct}»: ${typesWhy[correct]}.`;}
 if(q.family==='signs'&&q.type==='choice')return `Elegiste «${q.options[Number(value)]}», que normalmente ${signMeaning[Number(value)]}. Esta frase necesita «${q.options[q.answer]}»: ${signMeaning[q.answer]}.`;
 if(q.isLetter)return `Elegiste la ${q.options[Number(value)]}, pero esta palabra lleva ${q.options[q.answer]}. Comprueba la regla o excepción que la explica.`;
 if(q.type==='fill')return `Escribiste «${value}», pero la solución trabajada es «${q.answer}». Revisa las pistas de la regla o del ejemplo.`;
 return `La opción «${q.options[Number(value)]}» no responde a lo que se pregunta aquí. Fíjate en esta diferencia y repasa el razonamiento.`;
}
function feedbackHtml(q,value,correct,hinted=false){return `<section class="feedback ${correct?'':'bad'}" aria-live="polite"><h3>${correct?'🎉 ¡Muy bien! Has acertado.':'💡 Esta vez no, pero ahora lo entenderás.'}</h3>${!correct?`<p>${esc(wrongContrast(q,value))}</p>`:''}<div class="feedback-label">RESPUESTA CORRECTA</div><p class="answer-line">${esc(scoreLabel(q))}</p><div class="feedback-label">POR QUÉ ES ASÍ</div><p>${esc(q.why)}</p><div class="method"><div class="feedback-label">CÓMO RESOLVERLO PASO A PASO</div><p>${esc(q.how)}</p></div>${correct?`<p class="kicker">+${hinted?5:10} XP · ¡Seguimos!</p>`:'<p class="microcopy">Léelo una vez más antes de pasar al siguiente reto.</p>'}</section>`;}
function renderPracticePlay(){const s=practiceSession;if(!s)return renderPracticeSetup();const q=s.questions[s.index];if(!q)return renderPracticeSummary();
 $('#practiceContent').innerHTML=`<div class="game-panel"><div class="game-top"><span class="game-tag">${T(q.topic).emoji} ${esc(T(q.topic).label.toUpperCase())}</span><span class="game-count">PREGUNTA ${s.index+1} DE ${s.questions.length}</span></div><div class="meter" role="progressbar" aria-label="Progreso del reto" aria-valuenow="${s.index}" aria-valuemax="${s.questions.length}"><span style="width:${100*s.index/s.questions.length}%"></span></div><h2 class="question-prompt">${esc(q.prompt)}</h2><p class="question-sub">${q.isLetter?'Elige la letra correcta según las reglas de tus apuntes.':'Piensa tu respuesta antes de comprobarla.'}</p>${answerWidget(q,s.selected??s.input,s.answered)}${s.hinted?`<div class="hint">💡 <strong>PISTA:</strong> ${esc(q.hint||q.how)}</div>`:''}${s.answered?feedbackHtml(q,s.result.value,s.result.correct,s.hinted):''}<div class="game-actions">${!s.answered?`<div><button type="button" class="btn ghost small" id="giveHint" ${s.hinted?'disabled':''}>💡 ${s.hinted?'Pista mostrada':'Necesito una pista'}</button><button type="button" class="btn ghost small" id="giveUp">No lo sé</button></div><button type="button" class="btn primary" id="submitPractice">✅ Comprobar</button>`:`<span class="status-pill">${s.correct} aciertos en este reto</span><button type="button" class="btn primary" id="nextPractice">${s.index===s.questions.length-1?'🏁 Ver resultado':'Siguiente pregunta →'}</button>`}</div></div>`;
 if(!s.answered){const input=$('#freeAnswer');if(input){input.addEventListener('input',()=>{s.input=input.value;});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();evaluatePractice(false);}});}$$('[data-answer-choice]').forEach(b=>b.addEventListener('click',()=>{s.selected=Number(b.dataset.answerChoice);renderPracticePlay();}));$('#giveHint').addEventListener('click',()=>{s.hinted=true;renderPracticePlay();});$('#giveUp').addEventListener('click',()=>evaluatePractice(true));$('#submitPractice').addEventListener('click',()=>evaluatePractice(false));}else $('#nextPractice').addEventListener('click',()=>{s.index++;s.selected=null;s.input='';s.answered=false;s.hinted=false;s.result=null;renderPracticePlay();});
}
function evaluatePractice(giveup){const s=practiceSession,q=s.questions[s.index];let value=giveup?null:(q.type==='choice'?s.selected:$('#freeAnswer').value.trim());if(!giveup&&(value===null||value==='')){toast('Elige o escribe una respuesta primero.');return;}let correct=!giveup&&isCorrect(q,value);s.result={value,correct};s.answered=true;if(correct)s.correct++;markAnswer(q,correct,s.hinted);renderPracticePlay();}
function renderPracticeSummary(){const s=practiceSession;let rate=percent(s.correct,s.questions.length),emoji=rate>=85?'🏆':rate>=60?'🌟':'💪';$('#practiceContent').innerHTML=`<div class="game-panel" style="text-align:center"><div style="font-size:53px">${emoji}</div><div class="eyebrow">¡RETO FINALIZADO!</div><h2>${rate>=85?'¡Nivel estelar!':rate>=60?'¡Vas por buen camino!':'¡Cada reto suma!'}</h2><div class="result-score">${s.correct}/${s.questions.length}</div><p class="text-muted">${rate}% de respuestas acertadas. Tus fallos quedan guardados para poder repasarlos.</p><div class="result-grid"><div><strong>${s.correct}</strong><span>Aciertos</span></div><div><strong>${s.questions.length-s.correct}</strong><span>Para repasar</span></div><div><strong>${data.xp}</strong><span>XP acumulados</span></div></div><div class="options-row" style="justify-content:center"><button type="button" class="btn primary" id="practiceAgain">🔁 Otro reto</button><button type="button" class="btn outline" id="practiceTheory">📚 Repasar teoría</button><button type="button" class="btn ghost" id="practiceProgress">🏅 Ver progreso</button></div></div>`;$('#practiceAgain').addEventListener('click',()=>{practiceSession=null;renderPracticeSetup();});$('#practiceTheory').addEventListener('click',()=>{if(practiceConfig.topic!=='mezcla')selectedLesson=practiceConfig.topic;goPage('aprender');});$('#practiceProgress').addEventListener('click',()=>goPage('progreso'));}

function renderExam(){if(!examSession)return renderExamIntro();if(examSession.done)return renderExamResults();renderExamQuestion();}
function renderExamIntro(){let best=data.exams?`Ya has completado ${data.exams} ${data.exams===1?'simulacro':'simulacros'}. Mejor marca: ${data.bestExam} aciertos.`:'Aún no has hecho ningún simulacro. ¡Esta puede ser tu primera misión!';$('#examContent').innerHTML=`<div class="exam-panel"><div class="eyebrow">PRUEBA COMPLETA · LOS ${TOPICS.length} MUNDOS</div><h2>¿Lista para el gran reto?</h2><p>Las preguntas se seleccionan de forma aleatoria, por eso cada simulacro puede ser diferente.</p><div class="exam-rules"><div class="rule"><strong>🧩 ${EXAM_QUESTION_COUNT} preguntas</strong><span>${QUESTIONS_PER_TOPIC} de cada tema de clase</span></div><div class="rule"><strong>🕊️ A tu ritmo</strong><span>Sin cronómetro ni presión</span></div><div class="rule"><strong>💡 Corrección final</strong><span>Solución + explicación + método</span></div></div><p class="microcopy">${best}</p><button class="btn primary" id="startExam">📝 Empezar simulacro</button></div>`;$('#startExam').addEventListener('click',startExam);}
function startExam(){let q=shuffle(TOPICS.flatMap(t=>shuffle(topicQuestions(t.id)).slice(0,QUESTIONS_PER_TOPIC)));examSession={questions:q,index:0,selected:null,input:'',answers:[],done:false};renderExamQuestion();}
function renderExamQuestion(){const s=examSession,q=s.questions[s.index];$('#examContent').innerHTML=`<div class="exam-panel"><div class="game-top"><span class="game-tag">${T(q.topic).emoji} ${esc(T(q.topic).label.toUpperCase())}</span><span class="game-count">${s.index+1} / ${s.questions.length}</span></div><div class="meter" role="progressbar" aria-label="Progreso del simulacro" aria-valuenow="${s.index}" aria-valuemax="${s.questions.length}"><span style="width:${100*s.index/s.questions.length}%"></span></div><h2 class="question-prompt">${esc(q.prompt)}</h2>${answerWidget(q,s.selected??s.input)}<div class="game-actions"><span class="microcopy">La corrección se mostrará al finalizar el examen.</span><button class="btn primary" id="examNext">${s.index===s.questions.length-1?'🏁 Corregir examen':'Guardar y seguir →'}</button></div></div>`;
 const inp=$('#freeAnswer');if(inp){inp.addEventListener('input',()=>{s.input=inp.value;});inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveExamAnswer();}});}
 $$('[data-answer-choice]').forEach(b=>b.addEventListener('click',()=>{s.selected=Number(b.dataset.answerChoice);renderExamQuestion();}));$('#examNext').addEventListener('click',saveExamAnswer);
}
function saveExamAnswer(){const s=examSession,q=s.questions[s.index];const value=q.type==='choice'?s.selected:$('#freeAnswer').value.trim();if(value===null||value===''){toast('Necesitas responder antes de continuar.');return;}let correct=isCorrect(q,value);s.answers.push({id:q.id,value,correct});s.index++;s.selected=null;s.input='';if(s.index>=s.questions.length){s.done=true;data.exams++;let score=s.answers.filter(x=>x.correct).length;data.bestExam=Math.max(data.bestExam,score);for(const item of s.answers){let question=QUESTIONS.find(q=>q.id===item.id);markAnswer(question,item.correct,false);}persist();renderExamResults();}else renderExamQuestion();}
function renderExamResults(){const s=examSession,good=s.answers.filter(a=>a.correct).length,note=Math.round(good/s.questions.length*100),score10=note/10;const breakdown=TOPICS.map(t=>{let ids=s.questions.filter(q=>q.topic===t.id).map(q=>q.id),acc=s.answers.filter(a=>ids.includes(a.id)&&a.correct).length;return {topic:t,acc};});
 $('#examContent').innerHTML=`<div class="exam-panel" style="text-align:center"><div style="font-size:49px">${note>=80?'🏆':note>=50?'🌟':'🚀'}</div><div class="eyebrow">SIMULACRO CORREGIDO</div><h2>${note>=80?'¡Enhorabuena, misión conseguida!':note>=50?'¡Buen esfuerzo, sigue entrenando!':'¡Ya sabes qué necesitas repasar!'}</h2><div class="result-score">${score10.toFixed(1).replace('.',',')}<span style="font-size:20px"> / 10</span></div><p class="text-muted">${good} de ${s.questions.length} preguntas correctas (${note}%). No es una nota oficial; es una referencia para practicar.</p><div class="result-grid">${breakdown.map(b=>`<div><strong>${b.acc}/${QUESTIONS_PER_TOPIC}</strong><span>${b.topic.emoji} ${esc(b.topic.short)}</span></div>`).join('')}</div><div class="options-row" style="justify-content:center"><button class="btn primary" id="newExam">🔁 Nuevo simulacro</button><button class="btn outline" id="examReviewMistakes">🎮 Practicar mis fallos</button></div></div><h2 class="section-sub">🔍 Corrección explicada, pregunta por pregunta</h2><p class="text-muted">Lee el razonamiento de las incorrectas y comprueba también por qué las correctas lo son.</p><div id="examReviews">${s.questions.map((q,i)=>{let a=s.answers[i];return `<article class="review-card ${a.correct?'ok':'fail'}"><div class="review-meta">${a.correct?'✅ CORRECTA':'❌ PARA REPASAR'} · ${T(q.topic).short} · ${i+1}/${s.questions.length}</div><h4>${esc(q.prompt)}</h4><p><strong>Tu respuesta:</strong> <span class="${a.correct?'right-answer':'your-answer'}">${esc(valueLabel(q,a.value))}</span></p>${!a.correct?`<p>💡 ${esc(wrongContrast(q,a.value))}</p>`:''}<p><strong>Respuesta correcta:</strong> <span class="right-answer">${esc(scoreLabel(q))}</span></p><p><strong>Por qué:</strong> ${esc(q.why)}</p><p><strong>Cómo hacerlo:</strong> ${esc(q.how)}</p></article>`;}).join('')}</div>`;
 $('#newExam').addEventListener('click',()=>{examSession=null;startExam();});$('#examReviewMistakes').addEventListener('click',()=>{practiceConfig.topic='mezcla';practiceConfig.onlyMissed=true;practiceSession=null;goPage('practicar');});
}
function badges(){return [
 ['🌱','Primera estrella','Responde correctamente una pregunta.',data.correct>0],
 ['📚','Biblioteca completa','Visita la teoría de los seis mundos.',data.visited.length>=TOPICS.length],
 ['🔥','Superracha','Consigue 5 aciertos seguidos.',data.bestStreak>=5],
 ['📝','Gran simulacro','Completa al menos un simulacro.',data.exams>0],
 ['🌍','Vuelta al universo','Responde preguntas de los seis mundos.',TOPICS.every(t=>data.stats[t.id].answered>0)],
 ['🔎','Detective de sujetos','Acierta 10 preguntas de la oración.',data.stats.oracion.correct>=10],
 ['🅱️','Guardiana B/V','Acierta 10 preguntas de B y V.',data.stats.bv.correct>=10],
 ['🏆','Misión de honor','Logra al menos 12 aciertos en un simulacro.',data.bestExam>=12]
 ];}
function renderProgress(){let b=badges(),rate=percent(data.correct,data.answered),bestSubject=TOPICS.map(t=>({t,acc:data.stats[t.id].answered?percent(data.stats[t.id].correct,data.stats[t.id].answered):-1})).sort((a,b)=>b.acc-a.acc)[0];
 $('#progressContent').innerHTML=`<div class="progress-panel"><div class="progress-head"><div class="ring" style="--percent:${rate}%"><div class="ring-inner"><strong>${rate}%</strong><span>Aciertos totales</span></div></div><div><div class="eyebrow">RADIOGRAFÍA DE LA MISIÓN</div><h2>${data.answered?'¡Mira lo que has avanzado!':'¡Tu aventura empieza aquí!'}</h2><p class="text-muted">Has contestado <strong>${data.answered}</strong> preguntas y has acertado <strong>${data.correct}</strong>. Tu mejor racha es de <strong>${data.bestStreak}</strong> aciertos. Tienes <strong>${data.xp}</strong> puntos de experiencia.</p>${data.answered?`<p class="microcopy">Tu mejor tema por porcentaje ${bestSubject.acc>=0?`es ${esc(bestSubject.t.label)}`:'aún no está definido'}. El porcentaje es de intentos, no un diagnóstico de aprendizaje.</p>`:'<button class="btn primary" id="firstPractice">🎮 Empezar a practicar</button>'}</div></div><h3 class="section-sub">Tu rendimiento por tema</h3>${TOPICS.map(t=>{let s=data.stats[t.id],p=percent(s.correct,s.answered);return `<div class="topic-progress"><div class="topic-progress-top"><strong>${t.emoji} ${esc(t.label)}</strong><span>${s.correct} de ${s.answered} aciertos · ${p}%</span></div><div class="meter" style="margin:0"><span style="width:${p}%"></span></div></div>`;}).join('')}<div class="options-row" style="margin-top:24px"><button class="btn primary" id="progressTrain">🎯 Seguir entrenando</button><button class="btn outline" id="progressMissed" ${data.missedIds.length?'':'disabled'}>🔁 Repasar ${data.missedIds.length} fallos</button></div></div><h2 class="section-sub">🏅 Colección de insignias</h2><div class="achievements">${b.map(([icon,name,desc,unlocked])=>`<div class="achievement ${unlocked?'unlocked':''}"><span class="big">${icon}</span><b>${name}</b><p>${desc}</p><p>${unlocked?'✅ DESBLOQUEADA':'🔒 BLOQUEADA'}</p></div>`).join('')}</div><div class="setup-panel" style="margin-top:32px"><h3>⚙️ Datos de este navegador</h3><p class="microcopy">Todo se guarda de forma local, no se envía a ningún servidor. Si borras los datos del navegador, puedes perder tu progreso.</p><button class="btn danger small" id="resetData">Borrar mi progreso</button></div>`;
 const first=$('#firstPractice');if(first)first.addEventListener('click',()=>goPage('practicar'));
 $('#progressTrain').addEventListener('click',()=>{practiceConfig.onlyMissed=false;practiceSession=null;goPage('practicar');});
 $('#progressMissed').addEventListener('click',()=>{practiceConfig.topic='mezcla';practiceConfig.onlyMissed=true;practiceSession=null;goPage('practicar');});
 $('#resetData').addEventListener('click',()=>{if(!confirm('Se borrarán tus puntuaciones, fallos e insignias. El borrador de redacción se conservará. ¿Continuar?'))return;data=blankData();saveJSON(STORAGE_KEY,data);persist();renderProgress();toast('Progreso reiniciado');});
}
function initialize(){linkButtons();persist();renderHome();goPage(location.hash.slice(1)||'inicio');}
initialize();
